    # ERMModelT
    def Pack(self, builder):
        if self.ID is not None:
            ID = builder.CreateString(self.ID)
        if self.CALIBRATION_VERSION is not None:
            CALIBRATION_VERSION = builder.CreateString(self.CALIBRATION_VERSION)
        if self.CANDIDATE is not None:
            CANDIDATE = builder.CreateString(self.CANDIDATE)
        if self.BASIS_TEXT is not None:
            BASIS_TEXT = builder.CreateString(self.BASIS_TEXT)
        if self.PROPAGATOR is not None:
            PROPAGATOR = builder.CreateString(self.PROPAGATOR)
        if self.STRATA_SETTINGS is not None:
            STRATA_SETTINGS = self.STRATA_SETTINGS.Pack(builder)
        if self.HORIZONS_DAYS is not None:
            if np is not None and type(self.HORIZONS_DAYS) is np.ndarray:
                HORIZONS_DAYS = builder.CreateNumpyVector(self.HORIZONS_DAYS)
            else:
                ERMModelStartHORIZONS_DAYSVector(builder, len(self.HORIZONS_DAYS))
                for i in reversed(range(len(self.HORIZONS_DAYS))):
                    builder.PrependFloat64(self.HORIZONS_DAYS[i])
                HORIZONS_DAYS = builder.EndVector()
        if self.COUNTS is not None:
            COUNTS = self.COUNTS.Pack(builder)
        if self.QUANTILE_PROBABILITIES is not None:
            if np is not None and type(self.QUANTILE_PROBABILITIES) is np.ndarray:
                QUANTILE_PROBABILITIES = builder.CreateNumpyVector(self.QUANTILE_PROBABILITIES)
