        ERMModelStart(builder)
        if self.ID is not None:
            ERMModelAddID(builder, ID)
        if self.CALIBRATION_VERSION is not None:
            ERMModelAddCALIBRATION_VERSION(builder, CALIBRATION_VERSION)
        if self.CANDIDATE is not None:
            ERMModelAddCANDIDATE(builder, CANDIDATE)
        ERMModelAddFORM(builder, self.FORM)
