        if self.SOURCES is not None:
            ERMModelAddSOURCES(builder, SOURCES)
        ERMModelAddPOOLED(builder, self.POOLED)
        if self.PROVENANCE_REPOSITORY is not None:
            ERMModelAddPROVENANCE_REPOSITORY(builder, PROVENANCE_REPOSITORY)
        if self.PROVENANCE_COMMIT is not None:
            ERMModelAddPROVENANCE_COMMIT(builder, PROVENANCE_COMMIT)
        if self.PROVENANCE_FILES is not None:
            ERMModelAddPROVENANCE_FILES(builder, PROVENANCE_FILES)
        if self.LABEL is not None:
            ERMModelAddLABEL(builder, LABEL)
        ERMModel = ERMModelEnd(builder)
        return ERMModel
